#include <iostream>
#include <string>
#include <limits>

class Account {
private:
    int balance{0};

public:
    explicit Account(int initialBalance) {
        if (initialBalance >= 0) {
            balance = initialBalance;
        } else {
            balance = 0;
            std::cout << "Error: Initial balance was invalid.\n";
        }
    }

    void credit(int amount) {
        if (amount > 0 && amount <= std::numeric_limits<int>::max() - balance) {
            balance += amount;
        }
    }

    void debit(int amount) {
        if (amount > balance) {
            std::cout << "Debit amount exceeded account balance.\n";
        } else if (amount > 0) {
            balance -= amount;
        }
    }

    int getBalance() const {
        return balance;
    }
};

int main() {
    Account account1{50};
    Account account2{-10};

    std::cout << "account1 balance: " << account1.getBalance() << "\n";
    std::cout << "account2 balance: " << account2.getBalance() << "\n";

    account1.credit(25);
    std::cout << "account1 after credit 25: " << account1.getBalance() << "\n";

    account1.debit(100);
    std::cout << "account1 after debit 100: " << account1.getBalance() << "\n";

    account1.debit(40);
    std::cout << "account1 after debit 40: " << account1.getBalance() << "\n";

    return 0;
}

