class Invoice {
private:
    std::string partNumber;
    std::string partDescription;
    int quantity{0};
    int pricePerItem{0};

public:
    Invoice(std::string num, std::string desc, int qty, int price)
        : partNumber{std::move(num)}, partDescription{std::move(desc)} {
        setQuantity(qty);
        setPricePerItem(price);
    }

    void setQuantity(int qty) { quantity = (qty > 0) ? qty : 0; }
    int getQuantity() const { return quantity; }

    void setPricePerItem(int price) { pricePerItem = (price > 0) ? price : 0; }
    int getPricePerItem() const { return pricePerItem; }

    int getInvoiceAmount() const { if (pricePerItem != 0 && quantity > std::numeric_limits<int>::max() / pricePerItem) throw std::overflow_error("invoice overflow"); return quantity * pricePerItem; }
};

class Date {
private:
    int month{1};
    int day{1};
    int year{1900};

public:
    Date(int m, int d, int y) : day{d}, year{y} {
        setMonth(m);
    }

    void setMonth(int m) {
        month = (m >= 1 && m <= 12) ? m : 1;
    }
    int getMonth() const { return month; }

    void displayDate() const {
        std::cout << month << "/" << day << "/" << year << "\n";
    }
};

int main() {
    Invoice inv1{"P100", "Cordless Drill", 2, 75};
    Invoice inv2{"P200", "Screws", -10, 5};

    std::cout << "Invoice 1 amount: $" << inv1.getInvoiceAmount() << "\n";
    std::cout << "Invoice 2 amount (clamped): $" << inv2.getInvoiceAmount() << "\n";

    Date validDate{7, 4, 2024};
    Date invalidMonthDate{14, 1, 2024};

    std::cout << "Valid date: ";
    validDate.displayDate();
    std::cout << "Invalid month normalized: ";
    invalidMonthDate.displayDate();

    return 0;
}

